  g.strokeStyle = "rgba(240,230,200,0.18)"; g.lineWidth = 2 / s; for (let i = 0; i < 26; i++) { const xx = 380 + i * 18; g.beginPath(); g.moveTo(xx, -110); g.quadraticCurveTo(xx + 8, 0, xx, 90); g.stroke(); }
